                                    %dw 2.0
output application/java
var requestHeaders = (vars.aforoRequestHeaders default {}) mapObject ((value, key) -> {(lower(key as String)): value})
var mcpSession = requestHeaders.'mcp-session-id'
---
{
    method: vars.aforoRequest.method,
    requestPath: vars.aforoRequest.requestPath,
    requestId: vars.aforoRequest.requestId,
    requestContent: vars.aforoRequestContent,
    headers: requestHeaders ++ (if (mcpSession != null) {'Mcp-Session-Id': mcpSession} else {}),
    statusCode: attributes.statusCode,
    // Response size without reading (and buffering) the response body.
    responseContentLength: dw::Runtime::try(() -> (attributes.headers.'content-length' as Number)).result,
    responseTime: (now() as Number {unit: "milliseconds"}) - vars.aforoRequest.startedAtMs
}






                                    %dw 2.0
output application/json

// Policy properties, as the script below expects them.
var configuration = {
  "mcp-enabled": {{#if mcp-enabled}}true{{else}}false{{/if}},
  "mcp-product-id": "{{{mcp-product-id}}}",
  "status-outcomes": "{{{status-outcomes}}}",
  "exclude-status-codes": "{{{exclude-status-codes}}}",
  "exclude-paths": "{{{exclude-paths}}}",
  "product-type": "{{{product-type}}}",
  "default-metric": "{{{default-metric}}}",
  "metric-mappings": "{{{metric-mappings}}}",
  "quantity-source": "{{{quantity-source}}}",
  "include-metadata": "{{{include-metadata}}}",
  // Deprecated aliases (2.1.0 names). Read only when the property above is blank.
  "product_type": "{{{product_type}}}",
  "default_metric": "{{{default_metric}}}",
  "quantity_source": "{{{quantity_source}}}",
  "include_metadata": "{{{include_metadata}}}"
}
// `try` lives in dw::Runtime and returns {success, result}. The script
// below calls try(...) and expects the value or null.
fun try(delegate) = dw::Runtime::try(delegate).result

// >>> BEGIN metering script — the only copy; tests/policy.test.cjs locks its invariants
var requestBody = try(() -> read(attributes.requestContent, "application/json")) default null
var isMcpToolCall = (
  configuration.'mcp-enabled' == true and
  attributes.method == "POST" and
  requestBody != null and
  requestBody.jsonrpc == "2.0" and
  requestBody.method == "tools/call"
)
var toolName = if (isMcpToolCall) (requestBody.params.name default "unknown") else ""
var agentId = if (isMcpToolCall) (requestBody.params._meta.agent_id default "") else ""
var sessionId = attributes.headers.'Mcp-Session-Id' default ""

// ── Settings with a deprecated alias ──
// The canonical property wins; the alias is read only when it is blank.
fun setting(name, alias) = do {
  var canonical = trim((configuration[name] default "") as String)
  var fallback = if (alias == null) "" else trim((configuration[alias] default "") as String)
  ---
  if (canonical != "") canonical else fallback
}

// ── productType ── top-level on every event; the ingestor requires it.
// `product-type` (alias `product_type`), trimmed + upper-cased, default
// API. A tools/call is MCP_SERVER only when the request names an agent
// (the ingestor rejects MCP_SERVER without agentId); without one it keeps
// the configured type. A request with a trace id is AGENTIC_API (below).
var configuredProductType = upper(setting("product-type", "product_type"))
var productType = if (configuredProductType == "") "API" else configuredProductType
var mcpProductType = if ((agentId as String) != "") "MCP_SERVER" else productType

// occurredAt is ISO-8601 UTC: shift to UTC before formatting with a
// literal Z (formatting local time with a literal 'Z' mislabels it).
var occurredAtUtc = (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}

// ── Metric name ──
// 1. `metric-mappings`: rules "KIND|value|metricName" separated by ";",
//    KIND = EXACT, PREFIX or CONTAINS, compared with the request path as
//    plain text; the first matching rule wins.
// 2. `default-metric` (alias `default_metric`), default "api_calls". The
//    tokens {method} and {path} are replaced, so "{method} {path}"
//    restores the route-shaped name earlier builds sent.
// A name that is empty or longer than 255 characters is never sent: the
// event is dropped and the transport logs a WARN. The policy cannot know
// the catalog; a name the catalog lacks is rejected by the ingestor.
var requestMethod = (attributes.method default "UNKNOWN") as String
var requestPath = (attributes.requestPath default "/") as String
var metricRules =
  ((setting("metric-mappings", null) splitBy ";")
    map ((rule) -> (rule splitBy "|") map ((part) -> trim(part))))
    filter ((rule) -> (sizeOf(rule) == 3)
      and (["EXACT", "PREFIX", "CONTAINS"] contains upper(rule[0]))
      and (rule[1] != ""))
var matchedRule = (metricRules filter ((rule) ->
  if (upper(rule[0]) == "EXACT") requestPath == rule[1]
  else if (upper(rule[0]) == "PREFIX") requestPath startsWith rule[1]
  else requestPath contains rule[1]))[0]
var defaultMetricSetting = setting("default-metric", "default_metric")
var defaultMetric =
  ((if (defaultMetricSetting == "") "api_calls" else defaultMetricSetting)
    replace "{method}" with requestMethod) replace "{path}" with requestPath
var metricName = if (matchedRule != null) matchedRule[2] else defaultMetric
var isMetricSendable = (sizeOf(metricName) > 0) and (sizeOf(metricName) <= 255)

// ── Quantity ── `quantity-source` (alias `quantity_source`):
// "request_count" (default) -> 1; "response_size" -> the response
// Content-Length in bytes. The response body is never read. No
// Content-Length (chunked response) or 0 -> quantity 0 -> no event.
var quantitySource = lower(setting("quantity-source", "quantity_source"))
var quantity =
  if (quantitySource == "response_size")
    (if (attributes.responseContentLength is Number) attributes.responseContentLength else 0)
  else 1

// `include-metadata` (alias `include_metadata`): "false" leaves the
// metadata object off the event. Anything else, or blank, keeps it.
var includeMetadata = lower(setting("include-metadata", "include_metadata")) != "false"

// CORS preflight is never a billable call.
var isPreflight = upper(requestMethod) == "OPTIONS"

// ── Outcome classification (OUTCOME_BASED pricing) ──
// Maps the upstream HTTP status to the server's executionStatus value
// space. OUTCOME_BASED rate plans bill each event at a per-status
// weight; every other pricing model ignores the field. Shared rule —
// identical in all five gateway plugins (README "Execution status
// mapping"). Default table (policy locked 2026-09-30):
//   2xx/3xx -> SUCCESS, 408/504 -> TIMEOUT, 499 -> CANCELLED,
//   400/422 -> VALIDATION_FAILED, 401/403/429 -> BLOCKED,
//   every other 4xx and 5xx (404 included) -> ERROR,
//   unknown / 0 / missing / 1xx / out of range -> null (field OMITTED
//   via the conditional-field form below — never null or "").
// Overrides: the `status-outcomes` property ("404=VALIDATION_FAILED,
// 429=ERROR") — exact codes 200-599 win over the default; invalid
// entries are ignored; if a code is listed twice the last valid entry wins.
// The response payload is NOT inspected for JSON-RPC errors: Mule
// streams the response, and reading `payload` here would buffer it.
var allowedOutcomes = ["SUCCESS", "PARTIAL", "TIMEOUT", "ERROR",
  "VALIDATION_FAILED", "FAILED", "FAILURE", "CANCELLED", "PENDING",
  "BLOCKED", "HITL_REQUIRED"]
var statusOutcomeOverrides =
  (((configuration.'status-outcomes' default "") as String) splitBy ",")
    reduce ((part, acc = {}) -> do {
      var kv = trim(part) splitBy "="
      var code = trim(kv[0] default "")
      var outcome = upper(trim(kv[1] default ""))
      ---
      if ((sizeOf(kv) == 2) and (code matches /[2-5][0-9][0-9]/)
          and (allowedOutcomes contains outcome))
        // Drop an earlier entry for the same code first: ++ keeps both
        // keys and a lookup returns the FIRST, so without this the first
        // entry won. Last valid entry wins, as on the other four gateways.
        (acc - code) ++ {(code): outcome}
      else acc
    })
fun outcomeFromStatus(status) =
  if (not (status is Number)) null
  else if (status < 200 or status > 599) null
  else if (statusOutcomeOverrides[(status as String)] != null)
    statusOutcomeOverrides[(status as String)]
  else if (status < 400) "SUCCESS"
  else if (status == 408 or status == 504) "TIMEOUT"
  else if (status == 499) "CANCELLED"
  else if (status == 400 or status == 422) "VALIDATION_FAILED"
  else if (status == 401 or status == 403 or status == 429) "BLOCKED"
  else "ERROR"
var executionStatus = outcomeFromStatus(attributes.statusCode)

// AGENTIC_API classification — per descriptor
// eventSchema.inferenceRule = HAS_TRACE (agentic_api.json), an event
// with a resolvable trace id is classified as AGENTIC_API. Preferred
// source is the W3C traceparent header (parsed for its 32-hex
// trace_id field); fallback is x-trace-id per descriptor
// tracing.allowFallback = true (non-OTel callers). MCP JSON-RPC
// still wins the productType — the standard-event branch below is
// the only site that stamps AGENTIC_API. Malformed traceparent
// falls through cleanly; never invent a productType from an
// unparseable header.
var traceparentHeader = attributes.headers.'traceparent' default null
var xTraceIdHeader = attributes.headers.'x-trace-id' default null
var traceparentParts = if (traceparentHeader != null) (traceparentHeader splitBy "-") else []
// W3C format: version-trace_id-parent_id-flags (hex widths 2-32-16-2).
// Invalid per spec: version=="ff", trace_id all zeros, parent_id all zeros.
var isValidTraceparent = (
  sizeOf(traceparentParts) == 4 and
  traceparentParts[0] matches /^[0-9a-fA-F]{2}$/ and
  lower(traceparentParts[0]) != "ff" and
  traceparentParts[1] matches /^[0-9a-fA-F]{32}$/ and
  traceparentParts[1] != "00000000000000000000000000000000" and
  traceparentParts[2] matches /^[0-9a-fA-F]{16}$/ and
  traceparentParts[2] != "0000000000000000" and
  traceparentParts[3] matches /^[0-9a-fA-F]{2}$/
)
// Portable trim — `dw::core::Strings::trim` requires an explicit
// import in some Mule 4.x runtimes; the core `replace <regex> with`
// form is unambiguous across every DataWeave 2.0 version and needs
// no imports.
var trimmedXTrace = if (xTraceIdHeader != null) (xTraceIdHeader replace /^\s+|\s+$/ with "") else ""
// traceparent (W3C) takes precedence over x-trace-id (fallback).
var agenticTraceId = (
  if (isValidTraceparent) lower(traceparentParts[1])
  else if (sizeOf(trimmedXTrace) > 0) trimmedXTrace
  else null
)
var isAgenticApi = (not isMcpToolCall) and (agenticTraceId != null)

// ── Exclusions (requests that are NOT metered at all) ── [shared block]
// Same behaviour as Kong (exclude_status_codes / exclude_paths), AWS
// Lambda (EXCLUDE_STATUS_CODES), Apigee (KVM exclude_status_codes /
// exclude_paths) and Azure APIM (aforo-exclude-status-codes /
// aforo-exclude-paths): an excluded request yields an EMPTY events
// array, and the transport (template.xml) makes no outbound call for
// an empty array.
//   exclude-status-codes — CSV of HTTP codes. Absent or blank -> the
//     default 401,403,429. A value replaces the default. "none"
//     excludes nothing. Entries that aren't whole numbers 100-599 are
//     ignored.
//   exclude-paths — CSV of path prefixes. Absent or blank -> the
//     default /health,/ready,/metrics (Kong's default). A value
//     replaces the default; "none" excludes nothing. A path is excluded
//     when it equals an entry or starts with it.
// Never raises on malformed config: a value that is neither text nor a
// number is read as blank, and junk entries are dropped.
var defaultExcludeStatusCodes = [401, 403, 429]
var defaultExcludePaths = ["/health", "/ready", "/metrics"]
fun csvEntries(raw) = do {
  var text = if (raw is String) raw else if (raw is Number) (raw as String) else ""
  ---
  ((text splitBy ",") map ((entry) -> trim(entry))) filter ((entry) -> sizeOf(entry) > 0)
}
fun isExcludeNothing(entries) =
  (sizeOf(entries) == 1) and (lower(entries[0]) == "none")
var excludeStatusEntries = csvEntries(configuration.'exclude-status-codes')
var excludeStatusCodes =
  if (isEmpty(excludeStatusEntries)) defaultExcludeStatusCodes
  else if (isExcludeNothing(excludeStatusEntries)) []
  else (excludeStatusEntries filter ((entry) -> entry matches /[1-5][0-9][0-9]/))
    map ((entry) -> entry as Number)
var excludePathEntries = csvEntries(configuration.'exclude-paths')
var excludePaths =
  if (isEmpty(excludePathEntries)) defaultExcludePaths
  else if (isExcludeNothing(excludePathEntries)) []
  else excludePathEntries
var isExcludedStatus =
  (attributes.statusCode is Number) and (excludeStatusCodes contains attributes.statusCode)
var isExcludedPath =
  (attributes.requestPath is String) and
  (not isEmpty(excludePaths filter ((prefix) -> attributes.requestPath startsWith prefix)))
var isExcluded = isExcludedStatus or isExcludedPath
// ── end exclusions ── [shared block]

// Authenticated identity — set by aforo-jwt-validation policy.
// Never read X-Client-Id / X-Customer-Id / X-Tenant-Id from the
// request: they are client-settable and therefore spoofable.
var authenticatedCustomerId = vars.aforo.customerId default ""
var authenticatedTenantId = vars.aforo.tenantId default ""
var hasAuthenticatedIdentity = (authenticatedCustomerId != "") and (authenticatedTenantId != "")

// Why a request produces no event; null when it is metered. An MCP tool
// call always has quantity 1 and a fixed metric name.
var skipReason =
  if (isPreflight) "options"
  else if (isExcluded) "excluded"
  else if (not hasAuthenticatedIdentity) "no-identity"
  else if (sizeOf(authenticatedCustomerId) > 64) "customer-id-too-long"
  else if ((not isMcpToolCall) and (quantity <= 0)) "quantity"
  else if ((not isMcpToolCall) and (not isMetricSendable)) "metric"
  else null
var isMeterable = skipReason == null

---
{
  // Present only when the events array is empty, so it is never sent.
  (skipReason: skipReason) if (not isMeterable),
  // No event for OPTIONS, an excluded status code or path, a request
  // with no verified customer, a customer id over 64 characters, a
  // quantity of 0 or an unusable metric name.
  events: if (isMeterable) [
    if (isMcpToolCall) {
      customerId: authenticatedCustomerId,
      tenantId: authenticatedTenantId,
      metricName: "mcp_server.tool_invocations",
      quantity: 1,
      // Idempotency key FROZEN (A+ delivery-guarantee prompt 4): stable
      // request identity only — requestId + toolName is already unique
      // per invocation (one tools/call per HTTP request). The now()
      // suffix was removed: a per-evaluation clock makes every delivery
      // attempt look like a new event, defeating ingest dedup and
      // double-billing on redelivery. The uuid() fallback only fires
      // when requestId is absent and is materialized once into the
      // payload, so retries of the built payload still dedup.
      idempotencyKey: "mcp:mulesoft:" ++ (attributes.requestId default uuid()) ++ ":" ++ toolName,
      occurredAt: occurredAtUtc,
      productType: mcpProductType,
      toolName: toolName,
      agentId: agentId,
      sessionId: sessionId,
      // Shared outcome table: 2xx stays SUCCESS; 504 -> TIMEOUT (was ERROR).
      (executionStatus: executionStatus) if executionStatus != null,
      executionDurationMs: attributes.responseTime default 0,
      endpointPath: attributes.requestPath default "/",
      httpMethod: attributes.method default "UNKNOWN",
      statusCode: attributes.statusCode default 0,
      responseTimeMs: attributes.responseTime default 0,
      trace: {
        traceparent: attributes.headers.'traceparent' default null,
        tracestate: attributes.headers.'tracestate' default null,
        xTraceId: attributes.headers.'x-trace-id' default null,
        xRequestId: attributes.headers.'x-request-id' default null
      },
      (metadata: {
        gateway: "mulesoft",
        productId: configuration.'mcp-product-id' default "",
        status: attributes.statusCode,
        path: attributes.requestPath
      }) if includeMetadata
    } else {
      customerId: authenticatedCustomerId,
      tenantId: authenticatedTenantId,
      metricName: metricName,
      quantity: quantity,
      idempotencyKey: attributes.requestId default uuid(),
      occurredAt: occurredAtUtc,
      endpointPath: attributes.requestPath default "/",
      httpMethod: attributes.method default "UNKNOWN",
      statusCode: attributes.statusCode default 0,
      responseTimeMs: attributes.responseTime default 0,
      // Outcome for OUTCOME_BASED pricing (standard API + AGENTIC_API).
      (executionStatus: executionStatus) if executionStatus != null,
      // AGENTIC_API classification — top-level productType + traceId so
      // SchemaBasedEventValidator.getTopLevelField reads them via the
      // P0-6 DTO-first lookup (metadata is not searched for descriptor
      // requiredFields endpoint/method/status_code/trace_id).
      // Without a trace id the event carries the configured product type.
      productType: if (isAgenticApi) "AGENTIC_API" else productType,
      (traceId: agenticTraceId) if isAgenticApi,
      trace: {
        traceparent: attributes.headers.'traceparent' default null,
        tracestate: attributes.headers.'tracestate' default null,
        xTraceId: attributes.headers.'x-trace-id' default null,
        xRequestId: attributes.headers.'x-request-id' default null
      },
      (metadata: {
        gateway: "mulesoft",
        method: attributes.method,
        path: attributes.requestPath,
        status: attributes.statusCode
      }) if includeMetadata
    }
  ] else []
}
// <<< END shared script










                                            #[{
                                                "Content-Type": "application/json",
                                                "X-API-Key": "{{{aforo-api-key}}}"
                                            }]
